        # What about y? Same row.
        y_base = r*16+12
        x = scaled(x_base)
        y = scaled(y_base)
        body_parts.append(f'  <text x="{x}" y="{y}" >{esc}</text>')
    body = ""
    if body_parts:
        body = "\\n".join(body_parts) + "\\n"
        # Body parts are each with 2-space indent? Actually header/backdrop already have indent. Body lines should be "  <text..." with 2 spaces. Good.
